TEST(XPlatformSyscall, FnMatchBasicQuestionMark) {
  const std::string pattern("a?.doc");
  const std::string str("ab.doc");
  EXPECT_TRUE(XPlatform::Syscall::FnMatch(pattern, str));
}

TEST(XPlatformSyscall, FnMatchNegativeAsterisk) {
